    private static readonly int[] spaceRanges = [0x20,0x20,0xA0,0xA0,0x1680,0x1680,0x180E,0x180E,0x2000,0x200B,0x202F,0x202F,0x205F,0x205F,0x3000,0x3000];
    internal static bool IsSpace(int value) => Contains(spaceRanges,value);
    private static bool Contains(int[] ranges,int value)
    {
        int low=0,high=ranges.Length/2-1;
        while(low<=high)
        {
            int middle=(low+high)/2;
            if(value<ranges[middle*2])high=middle-1;
            else if(value>ranges[middle*2+1])low=middle+1;
            else return true;
        }
        return false;
    }
}
